package com.club.controller;
import com.club.dto.*; import com.club.enumeration.MedioPago; import com.club.service.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes; import java.util.List;
@RestController @RequestMapping("/api/familias") @RequiredArgsConstructor class FamiliaRestController { private final FamiliaService familia; private final PagoService pago; @PostMapping @ResponseStatus(HttpStatus.CREATED) public FamiliaResponse crear(@Valid @RequestBody RegistrarFamiliaDTO d){return familia.registrar(d);} @GetMapping public List<FamiliaResponse> listar(){return familia.listar();} @GetMapping("/{id}") public FamiliaDetalleResponse obtener(@PathVariable String id){return familia.obtenerDetalle(id);} @GetMapping("/{id}/pagos") public List<PagoResponse> pagos(@PathVariable String id){return pago.listarPorFamilia(id);} @PostMapping("/{id}/pagos") @ResponseStatus(HttpStatus.CREATED) public PagoResponse registrarPago(@PathVariable String id,@Valid @RequestBody RegistrarPagoDTO d){return pago.registrarPago(id,d);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void eliminar(@PathVariable String id){familia.eliminar(id);} }
@Controller @RequestMapping("/familias") @RequiredArgsConstructor public class FamiliaController { private final FamiliaService familia; private final SocioService socio; @GetMapping public String listar(Model m){m.addAttribute("familias",familia.listar());return "familias/lista";} @GetMapping("/nuevo") public String nuevo(Model m){m.addAttribute("form",new FamiliaForm());m.addAttribute("socios",socio.listar());return "familias/form";} @PostMapping public String crear(FamiliaForm f,Model m,RedirectAttributes ra){try{familia.registrar(new RegistrarFamiliaDTO(f.getNombre(),f.getCuotaMensual(),f.getTitularId()));ra.addFlashAttribute("ok","Familia registrada correctamente.");return "redirect:/familias";}catch(RuntimeException e){m.addAttribute("error",e.getMessage());m.addAttribute("socios",socio.listar());m.addAttribute("form",f);return "familias/form";}} @GetMapping("/{id}") public String detalle(@PathVariable String id,Model m){m.addAttribute("familia",familia.obtenerDetalle(id));m.addAttribute("personasDisponibles",socio.listar());return "familias/detalle";} @GetMapping("/{id}/editar") public String editarForm(@PathVariable String id,Model m){FamiliaDetalleResponse f=familia.obtenerDetalle(id);FamiliaForm form=new FamiliaForm();form.setNombre(f.nombre());form.setCuotaMensual(f.cuotaMensual());m.addAttribute("form",form);m.addAttribute("familia",f);return "familias/editar";} @PostMapping("/{id}/editar") public String editar(@PathVariable String id,FamiliaForm f,RedirectAttributes ra){try{familia.editar(id,new EditarFamiliaDTO(f.getNombre(),f.getCuotaMensual()));ra.addFlashAttribute("ok","Familia actualizada.");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/familias/"+id;} @PostMapping("/{id}/familiares") public String agregar(@PathVariable String id,@RequestParam String personaId,RedirectAttributes ra){try{familia.agregarFamiliar(id,personaId);ra.addFlashAttribute("ok","Familiar agregado.");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/familias/"+id;} @PostMapping("/{id}/familiares/{personaId}/eliminar") public String quitar(@PathVariable String id,@PathVariable String personaId,RedirectAttributes ra){try{familia.eliminarFamiliar(id,personaId);ra.addFlashAttribute("ok","Familiar quitado.");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/familias/"+id;} @PostMapping("/{id}/eliminar") public String eliminar(@PathVariable String id,RedirectAttributes ra){try{familia.eliminar(id);ra.addFlashAttribute("ok","Familia eliminada.");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/familias";} }
